s=s.replace('    --color-accent-soft: #eaf0f8;','    --color-accent-soft: #eaf0f8;\n    --color-paper-deep: #f1f5f9;\n    --color-shadow: rgba(15, 23, 42, .10);\n    --color-sidebar: #ffffff;\n    --color-sidebar-2: #f3f6fb;\n    --color-sidebar-ink: #17345f;\n    --color-sidebar-muted: #7183a0;\n    --color-sidebar-active: #eaf0f8;\n    --color-sidebar-border: #d8e0ec;')
s=s.replace('  .hoverRow:hover { background: #f8fafc; }','  .hoverRow:hover { background: #f8fafc; }\n  .nav-item { display:flex; align-items:center; gap:.65rem; min-height:36px; padding:.45rem .65rem; border:0; border-radius:9px; background:transparent; color:#334155; font-size:12px; font-weight:600; }\n  .nav-item:hover { background:#f3f6fb; color:#17345f; }\n  .nav-item-active { background:#eaf0f8; color:#17345f; font-weight:800; }\n  .nav-item-active svg { color:#17345f; }\n  .novacab-mail-grid { min-width:0; }\n  .novacab-welcome { position:relative; overflow:hidden; display:flex; align-items:center; justify-content:space-between; gap:24px; padding:22px 24px; margin-bottom:18px; border:1px solid var(--color-line); border-radius:16px; background:linear-gradient(135deg,#fff 0%,#f7f9fd 100%); box-shadow:0 8px 24px -18px var(--color-shadow); }\n  .novacab-welcome-glow { position:absolute; width:260px; height:260px; right:-80px; top:-120px; border-radius:50%; background:rgba(23,52,95,.06); pointer-events:none; }\n  .novacab-welcome-main { position:relative; min-width:0; z-index:1; }\n  .novacab-welcome-kicker { display:flex; align-items:center; gap:6px; color:#17345f; font-size:10.5px; font-weight:800; margin-bottom:7px; }\n  .novacab-welcome h1 { margin:0; color:#172033; font-size:24px; line-height:1.2; letter-spacing:-.02em; font-weight:800; }\n  .novacab-welcome p { max-width:760px; margin:6px 0 14px; color:#7183a0; font-size:11.5px; line-height:1.55; }\n  .novacab-welcome-actions { display:flex; gap:7px; flex-wrap:wrap; }\n  .novacab-welcome-actions button { display:inline-flex; align-items:center; gap:6px; border-radius:9px; padding:8px 11px; font-size:11px; font-weight:800; cursor:pointer; }\n  .novacab-welcome-primary { border:1px solid #17345f; background:#17345f; color:#fff; }\n  .novacab-welcome-secondary { border:1px solid #d8e0ec; background:#fff; color:#17345f; }\n  .novacab-welcome-ghost { border:1px solid transparent; background:transparent; color:#17345f; }\n  .novacab-welcome-summary { position:relative; z-index:1; flex:0 0 auto; display:grid; grid-template-columns:auto auto auto auto; align-items:center; gap:13px; padding:13px 15px; border:1px solid #d8e0ec; border-radius:13px; background:#fff; }\n  .novacab-welcome-summary-icon { width:34px; height:34px; display:flex; align-items:center; justify-content:center; border-radius:9px; background:#17345f; color:#fff; }\n  .novacab-welcome-summary-value { color:#17345f; font-size:20px; font-weight:800; line-height:1; }\n  .novacab-welcome-summary-label { color:#7183a0; font-size:9.5px; margin-top:3px; white-space:nowrap; }\n  .novacab-welcome-summary-divider { width:1px; height:30px; background:#d8e0ec; }\n  @media (max-width: 900px) { .novacab-welcome { align-items:flex-start; flex-direction:column; } .novacab-welcome-summary { width:100%; grid-template-columns:auto 1fr auto 1fr; } }\n  @media (max-width: 560px) { .novacab-welcome { padding:17px; } .novacab-welcome h1 { font-size:20px; } .novacab-welcome-summary { grid-template-columns:auto 1fr; } .novacab-welcome-summary-divider { display:none; } }')
